import{_ as r,l as i,o as a,c as l,v as s,p as o,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Jepsen","description":"","frontmatter":{"title":"Jepsen","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jepsen-testing.md","filePath":"cs/jepsen-testing.md","lastUpdated":1789023840000}'),h={name:"cs/jepsen-testing.md"};function E(_,e,m,u,f,A){const n=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=s('<h1 id="jepsen" tabindex="-1">Jepsen <a class="header-anchor" href="#jepsen" aria-label="Permalink to &quot;Jepsen&quot;">​</a></h1><div class="epigraph"><p>把网络分区、时钟与进程崩溃当成默认环境，再用线性一致性或声明的隔离级别去核对历史。绿基准盖不住红的 Jepsen 报告。</p><footer>—— Kingsbury, Jepsen 分析；分布式隔离与线性一致性文献对照</footer></div><p><a href="/cs/tpc-benchmarks">上一课</a>在正常负载下比吞吐。缺口是<strong>声明的隔离在分区下是否仍成立</strong>。本课钉 Jepsen 式对抗；行级安全下一课换访问控制。不提供针对具体产品的利用步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>厂商写「可串行化」或「线性一致」。Jepsen：生成客户端历史，注入 nemesis（分区、kill、时钟），用 Elle 等检查器找环。缺口是把<a href="/cs/failure-models">故障模型</a>接到数据库产品——即使该课在树后，机制相同。与 TPC：基准禁止恶意分区；Jepsen 专门恶意。</p><p><span class="marginnote">Kingsbury 的公开分析是方法来源。本课只讲如何读报告：历史、反例、是否改过默认配置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一份报告：集群拓扑、客户端、nemesis、检查器、反例是否可复述为隔离定义上的环。工程：把同一套故障注入接到 CI，但不要把随机 kill 当唯一测试。与 TLA+：规格先写，Jepsen 找实现偏离。</p>',8)),(a(),o(c,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E5%8E%86%E5%8F%B2%22%5D%20--%3E%20NEM%5B%22%E5%88%86%E5%8C%BA%20%2F%20%E5%B4%A9%E6%BA%83%22%5D%0A%20%20NEM%20--%3E%20CHK%5B%22%E9%9A%94%E7%A6%BB%20%2F%20%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%E6%A3%80%E6%9F%A5%22%5D%0A%20%20CHK%20--%3E%20BUG%5B%22%E5%8F%8D%E4%BE%8B%E7%8E%AF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>如果历史不能嵌入合法串行（或产品声明的级别），隔离声明失败。时钟跳变破坏依赖「本地时间」的 last-write-wins。多数派在分区下会脑裂，除非有仲裁。模型必须匹配产品承诺：把 SI 当可串行来检查会「误报」——其实是规格写错。异步提交应允许丢失，模型不能当同步 D。</p><p>超时 abort 应在历史里是 abort，不是静默丢。搜索引擎 refresh 前不可搜，若合同如此则不是 bug。与 wait-for：分区造成的永远等是故障检测，要进 nemesis。读己之写、单调读可单独当较弱模型测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写攻击 payload，不针对具体产品给利用步骤。下一课 RLS 是授权，不是共识。数据库审计收口责任，与 Jepsen 的「是否撒谎」互补。形式化 TLA+ 是规格先写，Jepsen 找实现偏离。</p><p>后课默认：分布式声明要用故障历史检验。吞吐基准不揭示脑裂双主。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Jepsen 用故障注入核对隔离声明，不是压测。</li><li>读报告看反例与默认配置，不看营销摘要。</li><li>行级安全下一课。</li><li>出处：Kingsbury Jepsen；线性一致性 / 隔离级别文献。</li></ul>',8))])}const T=r(h,[["render",E]]);export{B as __pageData,T as default};
